export type Ball = { x: number; y: number; vx: number; vy: number; r: number };

const W = 400;
const H = 300;
const R = 10;

export function make(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() - 0.5) * 6,
    vy: (Math.random() - 0.5) * 6,
    r: R,
  };
}

export function step(balls: Ball[]): void {
  for (const b of balls) {
    b.vy += 0.2;
    b.x += b.vx;
    b.y += b.vy;
    if (b.x < b.r) {
      b.x = b.r;
      b.vx = Math.abs(b.vx);
    } else if (b.x > W - b.r) {
      b.x = W - b.r;
      b.vx = -Math.abs(b.vx);
    }
    if (b.y < b.r) {
      b.y = b.r;
      b.vy = Math.abs(b.vy);
    } else if (b.y > H - b.r) {
      b.y = H - b.r;
      b.vy = -Math.abs(b.vy);
    }
  }

  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      let dx = b.x - a.x;
      let dy = b.y - a.y;
      let dist = Math.sqrt(dx * dx + dy * dy);
      const min = a.r + b.r;
      if (dist < min) {
        if (dist === 0) {
          dx = 1;
          dy = 0;
          dist = 1;
        }
        const nx = dx / dist;
        const ny = dy / dist;
        // separar las pelotas superpuestas
        const overlap = (min - dist) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
        // colisión elástica de igual masa: se intercambian las componentes normales
        const va = a.vx * nx + a.vy * ny;
        const vb = b.vx * nx + b.vy * ny;
        if (va - vb > 0) {
          const d = vb - va;
          a.vx += d * nx;
          a.vy += d * ny;
          b.vx -= d * nx;
          b.vy -= d * ny;
        }
        // mantener dentro del canvas tras la separación
        for (const p of [a, b]) {
          p.x = Math.min(W - p.r, Math.max(p.r, p.x));
          p.y = Math.min(H - p.r, Math.max(p.r, p.y));
        }
      }
    }
  }
}

export function draw(cv: HTMLCanvasElement | null, balls: Ball[]): void {
  if (!cv) return;
  const ctx = cv.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = "#f5f5f5";
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = "#3b82f6";
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

