use "./sim.ts" { make, step, draw }

page Sim "/" {
  state balls: Any[] = []
  state frames = 0
  state paused = false
  ref cv
  fn tick() {
    if !paused {
      step(balls)
      draw(cv, balls)
      frames++
    }
    requestAnimationFrame(tick)
  }
  fn reset() {
    balls = Array.from({ length: 5 }, () => make())
    frames = 0
  }
  fn addBall() {
    balls = [...balls, make()]
  }
  mount {
    reset()
    requestAnimationFrame(tick)
  }

  column gap=2 {
    canvas ref=cv id="sim" width=400 height=300
    text `Pelotas: ${balls.length}`
    text `Cuadros: ${frames}`
    row gap=2 {
      button "Agregar" -> addBall()
      button paused ? "Reanudar" : "Pausar" -> paused = !paused
      button "Reiniciar" -> reset()
    }
  }
}

